import Anthropic from '@anthropic-ai/sdk';
import { Page, TokenPage, PageCursor } from '@anthropic-ai/sdk/pagination';

const client = new Anthropic(); // reads ANTHROPIC_API_KEY from the environment

// Collect every item from any of the SDK's paginated list responses.
async function collectAll<T>(
  first: Page<T> | TokenPage<T> | PageCursor<T>,
): Promise<T[]> {
  const items: T[] = [];
  let page = first;
  while (true) {
    items.push(...page.getPaginatedItems());
    if (!page.hasNextPage()) break;
    page = await page.getNextPage();
  }
  return items;
}

async function main() {
  // Auto-pagination with `for await` (fetches further pages as needed).
  for await (const model of client.models.list({ limit: 20 })) {
    console.log(model.id, model.display_name);
  }

  // Manual pagination with the Page object.
  const page: Page<Anthropic.ModelInfo> = await client.models.list({ limit: 5 });
  console.log('first page:', page.data.map((m) => m.id));
  console.log('has more:', page.has_more, 'last_id:', page.last_id);

  if (page.hasNextPage()) {
    const next = await page.getNextPage();
    console.log('second page:', next.data.map((m) => m.id));
  }

  // Generic helper works for Page, TokenPage, and PageCursor results alike.
  const allModels = await collectAll(await client.models.list({ limit: 10 }));
  console.log('total models:', allModels.length);
}

main().catch((err) => {
  if (err instanceof Anthropic.APIError) {
    console.error(err.status, err.name, err.message);
  } else {
    console.error(err);
  }
  process.exit(1);
});

import Anthropic from '@anthropic-ai/sdk';

// In @anthropic-ai/sdk 0.135.0, `Anthropic.Page`, `Anthropic.TokenPage`, and
// `Anthropic.PageCursor` are no longer exported from the `Anthropic` namespace.
// Use the page objects returned by `list()` methods, and let TypeScript infer
// their types instead of naming the removed types.

const client = new Anthropic(); // reads ANTHROPIC_API_KEY from the environment

// Replaces `Anthropic.Page<Anthropic.ModelInfo>`.
type ModelsPage = Awaited<ReturnType<typeof client.models.list>>;
type ModelInfo = ModelsPage['data'][number];

async function listAllModelsAutoPaginated(): Promise<ModelInfo[]> {
  const models: ModelInfo[] = [];
  // Auto-pagination follows the cursor across pages.
  for await (const model of client.models.list({ limit: 20 })) {
    models.push(model);
  }
  return models;
}

async function listModelsPageByPage(): Promise<void> {
  let page: ModelsPage = await client.models.list({ limit: 5 });
  let pageNumber = 1;

  while (true) {
    console.log(
      `Page ${pageNumber}:`,
      page.data.map((m) => m.id),
    );

    if (!page.hasNextPage()) break;
    page = await page.getNextPage();
    pageNumber++;
  }
}

// Manual cursor handling replaces the old `Anthropic.PageCursor` params type.
async function listBatchesWithCursor(): Promise<void> {
  let afterId: string | undefined;

  do {
    const page = await client.messages.batches.list({
      limit: 10,
      ...(afterId ? { after_id: afterId } : {}),
    });

    for (const batch of page.data) {
      console.log(batch.id, batch.processing_status);
    }

    afterId = page.hasNextPage() ? page.data.at(-1)?.id : undefined;
  } while (afterId);
}

async function main(): Promise<void> {
  const all = await listAllModelsAutoPaginated();
  console.log(`Total models: ${all.length}`);

  await listModelsPageByPage();
  await listBatchesWithCursor();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

import OpenAI from "openai";
import { writeFile } from "node:fs/promises";

const client = new OpenAI(); // reads OPENAI_API_KEY from env

async function main() {
  // Create a video generation job and poll until it finishes
  let video = await client.videos.create({
    model: "sora-2",
    prompt: "A calico cat playing a tiny piano on a sunlit windowsill",
    seconds: "8",
    size: "1280x720",
  });

  while (video.status === "queued" || video.status === "in_progress") {
    await new Promise((r) => setTimeout(r, 5000));
    video = await client.videos.retrieve(video.id);
    console.log(`Status: ${video.status} (${video.progress ?? 0}%)`);
  }

  if (video.status !== "completed") {
    throw new Error(`Video generation failed: ${video.error?.message ?? video.status}`);
  }

  // Download the rendered MP4
  const content = await client.videos.downloadContent(video.id, { variant: "video" });
  const buffer = Buffer.from(await content.arrayBuffer());
  await writeFile("video.mp4", buffer);
  console.log("Saved video.mp4");

  // List recent videos
  for await (const v of client.videos.list({ limit: 5 })) {
    console.log(v.id, v.status, v.model);
  }

  // Remix the finished video with a new prompt
  const remix = await client.videos.remix(video.id, {
    prompt: "Same scene, but at night with moonlight",
  });
  console.log("Remix job:", remix.id, remix.status);

  // Clean up the original
  const deleted = await client.videos.delete(video.id);
  console.log("Deleted:", deleted.id, deleted.deleted);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

