import { QueryClient } from '@tanstack/react-query'

type Todo = { id: number; title: string; completed: boolean }

const queryClient = new QueryClient({
  defaultOptions: {
    queries: { staleTime: 60_000 },
  },
})

const todoQueryOptions = (id: number) => ({
  queryKey: ['todo', id] as const,
  queryFn: async (): Promise<Todo> => {
    const res = await fetch(`https://jsonplaceholder.typicode.com/todos/${id}`)
    if (!res.ok) throw new Error(`Failed to fetch todo ${id}`)
    return res.json()
  },
})

async function main() {
  // prefetchQuery: warm the cache; resolves to void and never throws
  await queryClient.prefetchQuery(todoQueryOptions(1))

  // fetchQuery: returns data; refetches if cached data is older than staleTime; throws on error
  const fresh = await queryClient.fetchQuery({
    ...todoQueryOptions(2),
    staleTime: 10_000,
  })
  console.log('fetchQuery:', fresh.title)

  // ensureQueryData: returns cached data if present, otherwise fetches it
  // revalidateIfStale triggers a background refetch when cached data is stale
  const ensured = await queryClient.ensureQueryData({
    ...todoQueryOptions(1),
    revalidateIfStale: true,
  })
  console.log('ensureQueryData:', ensured.title)

  // Read synchronously from the cache after prefetching
  const cached = queryClient.getQueryData<Todo>(['todo', 1])
  console.log('cached:', cached?.title)
}

main().catch(console.error)

import { QueryClient, queryOptions } from '@tanstack/react-query'

type Todo = { id: number; title: string; completed: boolean }

const queryClient = new QueryClient({
  defaultOptions: { queries: { staleTime: 60_000 } },
})

const todoOptions = (id: number) =>
  queryOptions({
    queryKey: ['todos', id],
    queryFn: async ({ signal }): Promise<Todo> => {
      const res = await fetch(`/api/todos/${id}`, { signal })
      if (!res.ok) throw new Error(`Failed to fetch todo ${id}`)
      return res.json()
    },
  })

// Replaces queryClient.ensureQueryData(options):
// returns cached data if present (never considered stale), otherwise fetches.
export function ensureTodo(id: number): Promise<Todo> {
  return queryClient.query({ ...todoOptions(id), staleTime: 'static' })
}

// Replaces queryClient.fetchQuery(options):
// returns cached data if fresh per staleTime, otherwise fetches. Throws on error.
export function fetchTodo(id: number): Promise<Todo> {
  return queryClient.query(todoOptions(id))
}

// Replaces queryClient.prefetchQuery(options):
// same as query(), but resolves to void and swallows errors.
export async function prefetchTodo(id: number): Promise<void> {
  await queryClient.query(todoOptions(id)).catch(() => undefined)
}

// Usage
async function main() {
  await prefetchTodo(1) // warm the cache, ignore failures

  const cached = await ensureTodo(1) // served from cache, no refetch
  console.log('ensured:', cached.title)

  try {
    const fresh = await fetchTodo(2) // fetched (or cached if still fresh)
    console.log('fetched:', fresh.title)
  } catch (err) {
    console.error('fetch failed:', err)
  }
}

